'use strict';
const baseScreen = screen;
const baseRender = render;
const baseSystem = renderSystem;
const art = (name,cls='',alt='')=>`<img class="scene-art ${cls}" src="assets/${name}.webp" alt="${alt}" decoding="async">`;
const sparkle=()=>`<span class="sparkle" aria-hidden="true">✳</span>`;
function editorialTitle(kicker,title,sub=''){return `<div class="editorial-title"><span class="kicker">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function newOnboard(id){const items={welcome:['Love lives in<br>the <em>little things.</em>','One thoughtful place for the meals, moments, and people that make their life lovely.','Begin their story','intro-care',0], 'intro-care':['Small rituals.<br><em>Happier days.</em>','A gentle rhythm for meals, walks, and everything in between. Less remembering. More being together.','Continue','intro-family',1], 'intro-family':['Their favorite<br><em>people. Together.</em>','See who did what, share the little updates, and make every handoff feel like home.','Continue','intro-health',2], 'intro-health':['Their whole world.<br><em>In your pocket.</em>','From vet records to sitter notes, keep their story close—even when you’re apart.','Create an account','signup',3]};let [title,sub,label,next,n]=items[id];return shell(`<div class="new-onboard"><div class="onboard-top"><span class="concept-mark">${icon('pet')} <b>Pet care</b></span><button class="text-btn" data-go="home">Explore</button></div><div class="onboard-scene scene-${n}"><div class="scene-orbit"></div>${art(n===3?'health-scene':n===1?'playful-dog':'cozy-friends','float-art',n===3?'A cat beside a violet care bag':'Playful illustrated pets')}<div class="floating-care-chip chip-one"><span class="chip-icon">${icon(n===3?'shield':n===2?'users':'heart')}</span><div><b>${['A little love, logged.','One good walk.','Alex took care of it.','Their story, together.'][n]}</b><small>${['Milo · Today, 8:02 AM','32 min · Milo & Alex','Evening meal · 6:00 PM','Records · Always close'][n]}</small></div></div><span class="scene-star star-one" aria-hidden="true">✳</span><span class="scene-star star-two" aria-hidden="true">✧</span><div class="orbit-dot"></div></div><h1>${title}</h1><p>${sub}</p><div class="onboard-pagination">${[0,1,2,3].map(i=>`<span class="${i===n?'active':''}"></span>`).join('')}<span class="page-label">0${n+1} / 04</span></div></div>`,'',`<div class="button-stack">${btn(label,next)}<button class="text-btn" data-go="signin">Already here? Sign in</button></div>`)}
function dailyTasks(){return state.tasks.filter(t=>!t.done).slice(0,3).map((t,i)=>`<div class="ritual-item" style="--i:${i}"><div class="ritual-time"><b>${t.sub.split(' · ')[0].split(' ')[0]}</b><small>${t.sub.split(' · ')[0].split(' ')[1]||'TODAY'}</small></div><span class="ritual-line"></span><button class="ritual-main" data-task="${t.id}"><span class="ritual-icon ${t.type==='food'?'peach':'lilac'}">${icon(t.type)}</span><span><b>${t.title}</b><small>${t.sub.split(' · ')[1]} · ${escapeHtml(petName())}</small></span></button><button class="check-btn" data-complete="${t.id}" aria-label="Complete ${t.title}"></button></div>`).join('')||`<div class="all-done"><span class="icon-tile green">${icon('check')}</span><div><b>All the little things, done.</b><p>Time to just enjoy each other.</p></div></div>`}
function newHome(){const name=escapeHtml(petName()),done=state.tasks.filter(t=>t.done).length,total=state.tasks.length,pct=Math.round(done/Math.max(1,total)*100);return shell(`<div class="today-top"><div class="greeting"><span class="kicker">FRIDAY, OCT 09</span><p>Hey, Emma ${sparkle()}</p></div><button class="icon-btn notification-dot" data-go="notifications" aria-label="Notifications">${icon('bell')}</button><button class="owner-avatar" data-go="account" aria-label="Your account">EW</button></div><div class="home-title"><h1>Their best day<br>starts with <em>you.</em></h1><span class="headline-spark" aria-hidden="true">✳</span></div>${petChips()}<div class="daily-hero"><div class="hero-copy"><span class="small-caps">${name}’S LITTLE WORLD</span><h2>Good days.<br>Happy tails.</h2><span class="hero-care-badge">${icon('heart')} Made of little things</span></div>${art(pet==='luna'?'health-scene':'playful-dog','hero-pet','A playful illustrated pet')}<div class="hero-progress"><div class="progress-heading"><span><b>${done}</b> of ${total} care moments</span><span>${pct}%</span></div><div class="progress-track"><span style="--progress:${pct}%"></span></div></div><span class="hero-star" aria-hidden="true">✧</span></div><div class="quick-label"><b>A little check-in</b><button data-go="log">All care</button></div><div class="new-quick-grid">${[['food','Meal','feeding','peach'],['walk','Walk','walk','lilac'],['pill','Medicine','medications','lime'],['heart','Mood','wellbeing','pink']].map(([i,t,to,c])=>`<button data-go="${to}"><span class="quick-bubble ${c}">${icon(i)}</span><b>${t}</b></button>`).join('')}</div><div class="section-head"><h3>Still to come<span class="count-pill">${total-done}</span></h3><button data-go="schedule">The full day</button></div><div class="ritual-list">${dailyTasks()}</div><button class="shared-moment" data-go="history"><div class="shared-avatars"><span class="avatar person">EW</span><span class="avatar person apricot">AC</span></div><div><b>A little teamwork.</b><p>Alex & you are making ${name}’s day.</p></div><span class="moment-spark" aria-hidden="true">✳</span></button>`,'home')}
function newPets(){return shell(`${heading('Their little world','Your favorite faces. Their care, together.','add-pet','plus')}<div class="pet-editorial-stack">${['milo','luna'].map((p,i)=>`<button class="pet-feature-card ${i?'cat-card':''}" data-open-pet="${p}"><img src="assets/${p}.webp" alt="${p==='milo'?'Golden retriever':'Gray cat'}"><span class="pet-type-tag">${p==='milo'?'THE ADVENTURER':'THE LITTLE DREAMER'}</span><div class="pet-feature-copy"><h2>${escapeHtml(p==='milo'?state.petName:state.catName)}<span>✳</span></h2><p>${p==='milo'?'Golden retriever · 3 years':'British shorthair · 2 years'}</p><div class="pet-metric-pills"><span>${p==='milo'?'28.4':'4.8'} kg</span><span>${p==='milo'?'3 care moments today':'2 care moments today'}</span></div></div><span class="pet-card-open">${icon('plus')}</span></button>`).join('')}</div><button class="new-pet-add" data-go="add-pet"><span class="icon-tile">${icon('plus')}</span><div><b>Room for one more?</b><p>Add a little friend to the family.</p></div></button>`,'pets')}
function newProfile(){const name=escapeHtml(petName());return shell(`${back('Their little world','pets',`<button class="text-btn" data-go="edit-pet">Edit</button>`)}<div class="profile-editorial"><img class="profile-editorial-photo" src="assets/${pet}.webp" alt="${name}"><span class="profile-bubble">${pet==='milo'?'Born to explore.':'Professional daydreamer.'}</span><div class="profile-photo-name"><span class="small-caps">YOUR ${pet==='milo'?'GOOD BOY':'LITTLE GIRL'}</span><h1>${name}<span>✳</span></h1></div></div><div class="profile-detail-band"><div><b>${pet==='milo'?'3':'2'}</b><span>years of love</span></div><div><b>${pet==='milo'?'28.4':'4.8'} <small>kg</small></b><span>latest weight</span></div><div><b>Apr 12</b><span>birthday</span></div></div><button class="health-feature" data-go="passport"><div><span class="small-caps">THEIR HEALTH, TOGETHER</span><h3>A little passport.<br>A whole lot of peace.</h3><span class="feature-link">Open health passport</span></div>${art('health-scene','','Cat and care kit illustration')}</button>${section('All the important things')}<div class="health-grid">${[['heart','Vaccinations','2 records','vaccines','pink'],['pill','Medication','Prescribed care','medications','lime'],['weight','Weight','Their progress','weight','lilac'],['file','Documents','3 saved files','records','peach']].map(([i,t,s,to,c])=>`<button class="health-grid-card ${c}" data-go="${to}"><span>${icon(i)}</span><b>${t}</b><small>${s}</small></button>`).join('')}</div><div class="card list-card" style="margin-top:18px">${listRow('Vet visits','A little planning ahead','calendar','visits')}${listRow('Emergency card','The contacts that matter','phone','emergency','pink')}</div>`,'pets')}
function newLog(){return shell(`${back('A little moment','home')}${editorialTitle('CARE, IN THE LITTLE THINGS','What did you<br>do <em>together?</em>')}${petChips()}<div class="log-art-band">${art('playful-dog','float-art','Happy dog illustration')}<div><span class="tag">EVERY MOMENT COUNTS</span><p>A meal. A walk.<br>A little extra love.</p></div></div><div class="log-grid">${[['food','A good meal','Food & water','feeding','peach'],['walk','A little walk','Time outside','walk','lilac'],['pill','Medication','Prescribed care','medications','lime'],['heart','A check-in','Mood & energy','wellbeing','pink'],['weight','Weight','New measurement','add-weight','lilac'],['edit','A care note','Something to remember','wellbeing','peach']].map(([i,t,s,to,c])=>`<button class="log-choice ${c}" data-go="${to}"><span class="log-choice-icon">${icon(i)}</span><b>${t}</b><small>${s}</small></button>`).join('')}</div>`,'log')}
function newCircle(){return shell(`${heading('Their favorite people','A little village. A lot of love.','invite','plus')}${petChips()}<div class="circle-editorial"><div class="circle-heading"><span class="small-caps">${escapeHtml(petName())}’S CARE CIRCLE</span><h1>Love is a<br><em>team effort.</em></h1></div><div class="circle-orbit"><span class="orbit-person person-one">EW<small>Emma</small></span><div class="orbit-pet">${photo(pet,'large')}</div><span class="orbit-person person-two">AC<small>Alex</small></span><span class="orbit-spark" aria-hidden="true">✳</span></div><div class="circle-caption"><span>${icon('shield')} A shared little world</span><span>2 caregivers</span></div></div>${section('The people who care','invite','Invite someone')}<div class="people-grid"><button data-go="member" class="person-card"><span class="avatar person">EW</span><b>Emma</b><small>Their person</small><span class="tag">Owner</span></button><button data-go="member" class="person-card"><span class="avatar person apricot">AC</span><b>Alex</b><small>Walks & adventures</small><span class="tag orange">Caregiver</span></button></div><button class="sitter-feature" data-go="handoff"><div><span class="small-caps">AWAY FOR A WHILE?</span><h3>Leave a guide.<br>Take peace of mind.</h3><span class="feature-link">Create a sitter handoff</span></div>${art('cozy-friends','','Cozy dog and cat')}</button>${section('A little update','history')}${entry('walk','Alex made time for a walk.','9:18 AM · Milo · 32 happy minutes')}`,'circle')}
function newPassport(){return shell(`${back('Their health story','profile')}${editorialTitle('IMPORTANT THINGS, BEAUTIFULLY TOGETHER','A little passport.<br><em>A whole story.</em>')}<div class="passport-editorial"><div class="passport-top"><span>PET CARE PASSPORT</span><span>01 / HEALTH</span></div><div class="row">${photo(pet,'large')}<div><h2>${escapeHtml(petName())}</h2><p>${pet==='milo'?'Golden retriever':'British shorthair'}</p><span class="tag">Their story, always close.</span></div></div><div class="passport-perforation"></div><div class="detail-grid">${info('Birthday','12 Apr 2023')}${info('Latest weight',pet==='milo'?'28.4 kg':'4.8 kg')}${info('Microchip','985 141 004 123 456')}${info('Care contact','Emma Williams')}</div><div class="passport-footer"><span>${icon('shield')} Shared only by you</span><span aria-hidden="true">✳</span></div></div>${section('Inside their story')}<div class="card list-card">${listRow('Vaccination records','Their recorded protection','heart','vaccines','pink')}${listRow('Medication notes','Vet-provided instructions','pill','medications','green')}${listRow('Contacts & emergencies','The people to call','phone','emergency')}${listRow('Health documents','All the important records','file','records')}</div><p class="small muted" style="line-height:1.6">A care summary, not an official travel certificate.</p>`,'',action('Export their care story','export-passport'))}
function newSuccess(id){return shell(`<div class="illustrated-success"><div class="success-art-halo">${art('cozy-friends','float-art','Cozy dog and cat')}<span class="success-seal">${icon('check')}</span><span class="success-spark" aria-hidden="true">✳</span></div><span class="kicker">${id==='ready'?'A NEW CHAPTER':'A LITTLE LOVE, LOGGED'}</span><h1>${id==='ready'?'Here’s to more<br><em>good days.</em>':'Small moment.<br><em>Big love.</em>'}</h1><p>${id==='ready'?escapeHtml(petName())+'’s care home is ready. Let their story begin.':'It’s all in their timeline. Your care circle is in the loop.'}</p>${id==='care-saved'?`<div class="success-receipt">${photo()}<div><b>${state.history[0]?escapeHtml(state.history[0].title):'Care logged'}</b><p>Emma · Just now</p></div><span>${icon('check')}</span></div>`:''}</div>`,'',`<div class="button-stack">${btn('Back to their day','home')}${btn(id==='ready'?'Invite their people':'See the little moments',id==='ready'?'invite':'history','secondary')}</div>`)}
const illustratedSections={'vaccines':['health-scene','A little protection.','Their recorded care, all together.'],'medications':['health-scene','Care, with clarity.','Prescribed instructions, kept close.'],'records':['health-scene','Their little paper trail.','The important details, remembered.'],'visits':['health-scene','A little planning.','More peace of mind.'],'reminders':['playful-dog','One less thing to remember.','A gentle rhythm for their day.'],'more':['cozy-friends','Make yourself at home.','A few little things, just for you.']};
screen=function(id){if(id==='welcome'||id.startsWith('intro-'))return newOnboard(id);if(id==='home')return newHome();if(id==='pets')return newPets();if(id==='profile')return newProfile();if(id==='log')return newLog();if(id==='circle')return newCircle();if(id==='passport')return newPassport();if(id==='care-saved'||id==='ready')return newSuccess(id);let html=baseScreen(id);if(illustratedSections[id]){const [a,t,s]=illustratedSections[id];const marker=`<div class="section-illustration"><div><span class="small-caps">THE LITTLE THINGS</span><h3>${t}</h3><p>${s}</p></div>${art(a,'','Pet-care illustration')}</div>`;html=html.replace('<div class="mobile-scroll">','<div class="mobile-scroll">'+marker)}return html};
let previousScreen='';render=function(){const same=previousScreen===current&&view==='prototype';const y=document.querySelector('#phone-content .mobile-scroll')?.scrollTop||0;baseRender();const p=document.getElementById('phone-content');if(view==='prototype'){p.dataset.screen=current;if(same){const sc=p.querySelector('.mobile-scroll');if(sc)sc.scrollTop=y}else{p.classList.remove('screen-enter');void p.offsetWidth;p.classList.add('screen-enter')}previousScreen=current}document.querySelectorAll('.gallery-phone').forEach(el=>el.setAttribute('inert',''))};
renderSystem=function(){baseSystem();const el=document.getElementById('system-view');el.innerHTML=el.innerHTML.replace('THE BRAND / PET CARE','VISUAL DIRECTION / CONCEPT 02').replace('<h1>Pet care</h1>','<h1>Name<br>undecided.</h1>').replace('WORKING BRAND · V1.0','VISUAL IDENTITY EXPLORATION · 02').replace('A little care.<br>A lot of love.','Love, in the<br><em>little things.</em>').replace('assets/friends.webp','assets/cozy-friends.webp').replace("A cheerful, practical companion for people who share life with pets. Care feels simple, human, and connected.","An editorial, expressive direction for shared pet care. Vivid violet, a little lime, original tactile illustrations, and motion that celebrates the moments that matter.");el.innerHTML=el.innerHTML.replace(/#2854F4/g,'#7549EF').replace(/#FF9F4B/g,'#DDF688').replace(/#17203B/g,'#262139').replace(/#F4F6FB/g,'#F8F7FC').replace('Pet care blue','Electric violet').replace('Apricot','Lime zest').replace('Warm accents','Playful highlights');el.insertAdjacentHTML('beforeend',`<div class="system"><h2 class="system-title">A little motion. A lot of intention.</h2><div class="motion-gallery"><div class="motion-card"><div class="motion-scene">${art('playful-dog','float-art','Animated floating dog illustration')}</div><h3>Gentle life in the artwork.</h3><p>Slow 6-second breathing motion. Pause on hover. Never applied to text or clinical instructions.</p></div><div class="motion-card"><div class="motion-scene motion-violet">${art('cozy-friends','float-art','Animated cozy pet illustration')}</div><h3>Transitions with a rhythm.</h3><p>280 ms fade-and-rise between screens; 60 ms stagger in care lists. Active buttons respond to touch.</p></div><div class="motion-card"><div class="motion-scene motion-lime">${art('health-scene','float-art','Illustrated cat beside a care kit')}</div><h3>Feedback you can feel.</h3><p>Progress grows to the current value. Completing a task adds a brief celebratory burst. Reduced-motion preferences are respected.</p></div></div><h2 class="system-title">New illustration suite.</h2><div class="asset-grid">${[['playful-dog','The little adventurer'],['cozy-friends','Their happy place'],['health-scene','Care, kept close']].map(([f,t])=>`<div class="illustration-download"><img src="assets/${f}.webp" alt="${t}"><p>${t} · Original AI-generated artwork</p><a class="text-btn small" href="assets/${f}.webp" download="pet-care-${f}.webp">Download illustration</a></div>`).join('')}</div></div>`)};
const previousClickAction=handleAction;handleAction=function(a){if(a==='confirm-dose'){previousClickAction(a);celebrate();return}previousClickAction(a)};
function celebrate(){if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelector('.celebration-layer')?.remove();let layer=document.createElement('div');layer.className='celebration-layer';layer.setAttribute('aria-hidden','true');layer.innerHTML=Array.from({length:14},(_,i)=>`<i style="--x:${(i%7-3)*29}px;--y:${-50-i%5*22}px;--r:${i*43}deg;--c:${['#7549ef','#ddf688','#ffa664','#ed82af'][i%4]};--delay:${i*18}ms"></i>`).join('');document.getElementById('phone').append(layer);setTimeout(()=>layer.remove(),1400)}
document.addEventListener('click',e=>{if(e.target.closest('[data-complete]'))celebrate();if(e.target.closest('[data-action="task-done"]'))celebrate()});
// Keep illustration motion optional and preview only the approved visual direction.
const motionButton=document.createElement('button');motionButton.className='motion-control';motionButton.setAttribute('aria-pressed','true');motionButton.textContent='Motion on';motionButton.onclick=()=>{const off=document.body.classList.toggle('motion-off');motionButton.textContent=off?'Motion off':'Motion on';motionButton.setAttribute('aria-pressed',String(!off))};document.querySelector('.stage-controls').prepend(motionButton);
render();
